FALLBACK_POLICY_BY_POST_ID.update({
    "12827844": (
        "龙岗区低空经济产业政策扶持企业申报指南（2026年度第一批）",
        "2026年度龙岗区低空经济产业政策扶持面向2025年度符合条件的企业开放申报。支持对象是在龙岗区实际经营，主营业务为通用航空、无人驾驶航空器制造、低空相关软硬件开发及系统设计与建设，低空飞行、运营服务及保障等低空经济领域企业、社会组织及其他单位。扶持方向包括无人机综合测试基地运营、低空前沿技术落地转化、低空载人航线服务。无人机综合测试基地运营按不超过实际年度运营费用的50%给予补贴，同一项目已获上级财政资金扶持的，按照未达50%的差额部分予以补贴，每年最高不超过300万元。推动低空前沿技术落地转化，对符合条件的单位每年给予2500万元扶持。支持开设低空载人航线服务，经产业主管部门备案后可依据龙岗区低空消费相关文件申请乘用奖励，年度奖励总额不超过1500万元。基础条件包括在龙岗区实际经营、未列入严重失信主体名单、材料真实合法完整、生产经营数据真实可靠、不得以同一事项重复申报或多头申报区级专项资金。测试基地需具备试飞测试、研究试验、产品检验、质量检测等功能，申报前正式投入运营，具备完整运营记录与服务合同，运营费用需经第三方审计确认。低空前沿技术落地转化申报主体需在龙岗区实际经营，办公场地不少于1000平方米，常驻研发与管理人员不少于50人，近三年参与省级以上课题或重大科研项目不少于2项，发表高水平论文或专著不少于5篇本，主导制定低空经济行业标准不少于1项、团体标准不少于2项，资助年度开展实质性合作不少于2项，申请发明专利不少于30项，政策期满累计授权发明专利不少于60项。低空载人航线服务需在龙岗区开通并稳定经营不少于5条低空载人航线，航线已备案，具备完整飞行记录，经营情况经第三方审计确认。申报资料包括申报书、单位简介、营业执照、法定代表人身份证、项目负责人身份证、低空经济领域知识产权证明、信用报告，以及不同项目对应的规划证明、运营记录、服务合同、费用明细、专项审计报告、课题项目证明、标准材料、合作协议、专利材料、航线备案文件和飞行记录。",
    ),
    "12826107": (
        "2026年度深圳市研发费用资助项目申请指南",
        "为鼓励企业、高等院校、科研机构、医疗卫生机构等各类创新主体坚持长期主义，持续加大研发投入，推动全社会研发投入保持高增长和优化投入结构，深圳市研发费用资助项目对2025年度研发费用较2024年度增量200万元含以上的单位，针对研发费用增量情况分档予以事后资助。支持强度为结合当年度符合条件单位数量和预算规模，根据单位研发费用增长幅度分档给予梯度资助，每家单位年度内资助资金最低不少于20万元，最高不超过300万元。注册成立时间不足两个会计年度的企业和上年度首次纳入R&D经费统计的高等院校、科研机构、医疗卫生机构，可按最近一个会计年度研发费用或R&D经费支出额中横向经费和市外纵向经费之和，参照档位和金额给予支持。申请单位应依法注册，在深圳市含深汕特别合作区实际从事经营活动并具有独立法人资格。企业注册成立两个会计年度含以上的，2025年和2024年均应已申报享受研发费用税前加计扣除，且2025年度研发费用较2024年增量达200万元含以上；注册成立时间不足两个会计年度且2024年未申报享受加计扣除的，2025年已申报享受研发费用税前加计扣除且2025年研发费用达200万元含以上。高等院校、科研机构、医疗卫生机构连续两年纳入R&D经费统计的，2025年R&D经费支出额中横向经费与市外纵向经费之和较2024年增量达200万元含以上；首次纳入统计的，相关经费之和达200万元含以上。单位诚信记录应良好，不存在被限制申请财政性资金项目惩戒情形，不存在项目超期未申请验收和超期未退款情形。",
    ),
    "12817823": (
        "2026年度深圳市中小试基地认定资助项目申请指南",
        "2026年度深圳市中小试基地认定资助项目鼓励高等院校、科研机构、企业和社会组织开展产业技术研发与转化，重点面向行业内中小企业提供科研成果和实验技术的二次开发、小试试验、中试放大、工程化和工艺化等中小试验证服务和研发设计外包服务，解决科技成果产业化过程中验证周期长、难度大、熟化慢、成本高等痛点，重点支持深圳市战略性新兴产业集群和未来产业领域。资助资金按照不超过申请单位经第三方审计机构出具的上两个年度扣除各级财政资助资金后实际投入的中小试服务费用予以支持，单个项目最高不超过1000万元，支持方式为事后补助。申请单位应在深圳市含深汕特别合作区依法实际从事经营活动，具备法人资格，可为高等院校、科研机构、企业和社会组织，鼓励高等院校、科研机构与企业联合申报建设。申请单位应制定完善的中小试基地建设方案，具有明确目标、完整服务和运行管理制度。申请单位应建立中小试项目库，入库项目不少于5个，并对外提供中小试服务。基地应具备良好的中小试工艺开发、优化验证和产品检测条件，承担行业综合性中间试验任务必备场地面积不少于2000平方米，拥有中小试工艺验证、放大生产和产品检测必备的专用设备、通用计量、测试仪器及专用软件原值不低于1000万元，并具备必要安全、环保设施装备。联合申报参与单位最多不超过2个，合作协议应明确任务分工、知识产权分配和服务收益分配。中小试基地主任应熟悉中小试方案设计、工艺设计、质量控制等全流程，具有本科含以上学历或中级含以上职称。服务人才团队应聘任相关领域中小试专业工程师不少于2名，团队总人数不少于10人，其中专职服务人员不少于5人，具有本科含以上学历或中级含以上职称的人员不低于总人数的50%。项目遴选顾问专家团队总人数不少于5人，并由学术界、产业界和投资界专家组成。申请单位、基地主任及服务人才团队成员不得存在财政性资金项目惩戒情形，不得委托中介机构申报，同一项目不得多头和重复申报，基地专职人员、研发场地及中小试仪器设备不得与其他市级及以上创新载体重复；涉及科技伦理和科技安全的，应符合国家有关法律法规和伦理准则。同一申请单位申请项目不超过2个。",
    ),
    "12809327": (
        "2026年度深圳市重点实验室组建资助项目申请指南",
        "深圳市重点实验室是深圳科技创新体系的重要组成部分，围绕国家战略和省市产业发展需要，打造科技创新与产业发展并举、教育科技人才一体化融合发展的高能级创新平台。本次申报分为基础研究类和应用研究类重点实验室，基础研究类主要依托高校、科研院所、医疗卫生机构等建设，应用研究类主要依托研发投入力度大、研发条件好的企业建设，也可依托高校、科研院所、医疗卫生机构等建设。市科技研发资金给予重点实验室组建资助，支持数量受年度总额控制，每家申请单位最多立项2个，单个最高资助500万元；依托单位为企业的，资助额不高于项目总预算的50%，支持方式为事前资助。申请单位应在深圳市含深汕特别合作区具有独立法人资格，可为高校、科研院所、医疗卫生机构、企业和社会组织或依法批准设立的其他机构。拟组建实验室定位和目标应清晰，研究方向明确，且不与其他市级及以上已建重点实验室重复，研究内容具有前瞻性和特色并与实验室名称相符合。实验室固定人员应在20人以上，人员结构合理且不与其他市重点实验室固定人员重复；科研用房面积应在700平方米以上，科研仪器设备原值不低于700万元，软件领域实验室原值不低于400万元。实验室固定成员近2年被SCI、EI、ISTP、ISR等收录论文及授权知识产权合计不少于20项，其中SCI、EI期刊论文及授权发明专利、软件著作权、集成电路布图设计专有权、植物新品种合计不少于10项。高校、科研院所、医疗卫生机构和社会组织等申请的，固定成员近2年以申请单位名义主持承担与研究方向相关的省部级以上科研项目不少于7项，其中国家级项目不少于1项，立项总金额在700万元以上。企业申请的，近2年主营业务收入应超过5亿元每年且研发经费占主营业务收入比例不低于3%，或近2年研发经费达到4000万元每年以上。申请单位还需为实验室持续稳定提供人员、场地、经费等必要条件支持保障。",
    ),
    "12809968": (
        "2026年度技术转移和成果转化资助项目申请指南",
        "2026年度技术转移和成果转化资助项目为推动技术交易和促进科技成果转化，培育专业性强、特色明显的技术转移机构，对经深圳市技术合同登记机构认定登记的技术合同项目，以及向深圳企业输出技术或成果的高校科研院所、具备独特商业模式和核心竞争力的技术转移机构、技术转移人才培育机构予以支持。技术合同资助项目按不超过申请单位2024年技术交易收入额的3%予以资助，最高不超过200万元；其中技术开发合同合计资助最高不超过100万元，技术转让合同、技术许可合同、技术咨询合同和技术服务合同等每类合同合计资助最高不超过25万元，每类合同最多申报20份。技术交易收入取技术合同核定技术交易额、2024年合同发票金额、对应银行流水账单三者中的最小值，以不含税金额确认。发票购货方与销货方、银行流水付款方与收款方需与技术合同认定登记证明信息一致，发票内容需与申报合同类型对应；资助金额低于5万元的不予支持。技术转移机构培育项目中，高校科研院所技术转移培育按2024年经审计在深圳投入技术转移专项费用的50%资助，最高100万元，累计不超过三年；技术转移特色基地培育按专项费用50%资助，最高500万元，累计不超过三年；技术转移人才培养基地培育按专项费用50%资助，最高100万元，累计不超过三年。2026年度资助数量不超过10个高校科研院所技术转移培育项目、5个技术转移特色基地、3个技术转移人才培养基地。技术合同资助申请单位应在深圳实际经营或运营，为技术合同卖方或受托方，技术合同应在2024年经深圳市技术合同登记机构认定登记，登记证明编号前缀为4403012024，且未享受过减免流转税优惠政策。技术转移特色基地需设立并运营2年以上，具有固定经营场所、稳定客户群和长期合作伙伴，服务企业不少于10家，2024年转移转化科技成果不少于5项或近两年不少于8个，2024年营业性收入不低于500万元或投入科技成果转移转化专项经费不低于1000万元，综合性技术转移机构专职人员在3人以上。技术转移人才培养基地需师生比不低于1比20，与2家以上大中型企业建立稳定合作，非高校还需至少与1家高校合作，2024年在深圳培育技术转移人数不低于200人。相关项目不得委托中介机构申报，同一项目不得多头和重复申报，专项费用不得包括各级财政资助资金。",
    ),
})

