FALLBACK_POLICY_BY_POST_ID.update({
    "20260006": (
        "深圳市商务局2026年服务贸易发展扶持计划（服务贸易创新发展扶持项目）申报指南",
        "本项目支持数字贸易加快发展、检验检测服务等专业服务高端化国际化发展、保险领域企业和机构创新适合服务贸易的金融产品和服务，并鼓励承接高增值型服务外包业务。支持方式为事后资助或奖励，企业自愿申报，受财政年度预算控制。推动数字贸易方向以2025年1月1日至2025年12月31日期间实际服务出口额作为排名依据，软件产品或软件研发服务年度实际服务出口额不低于2000万美元；云计算、大数据、区块链、人工智能服务不低于300万美元；社交媒体、搜索引擎、卫星定位服务不低于500万美元；数字内容服务不低于200万美元；数字游戏服务不低于500万美元；检验检测服务不低于300万美元；保险服务不低于500万美元。符合数字贸易1至6项并排名靠前的企业每家给予一次性100万元资金奖励，保险服务排名靠前的企业或机构每家给予一次性200万元资金奖励。服务外包方向支持信息技术外包和知识流程外包，高增值型服务外包年度实际服务出口额不低于1000万美元，排名靠前企业每家一次性100万元资金奖励。申报主体应在深圳市含深汕特别合作区实际从事经营活动，按要求在商务部业务系统统一平台进行业务登记和统计填报，不得严重失信，不得以同一事项重复或多头申报市级专项资金。网络填报时间为2026年7月3日至2026年7月30日18:00，材料提交时间为2026年7月6日至2026年8月3日17:30。受理机关和决定机关为深圳市商务局。"
    ),
})

