        "2026年度知识产权国内维权能力提升资助项目申报指南",
        "本项目依据《深圳市市场监督管理局知识产权领域专项资金操作规程》（深市监规〔2024〕5号）设立，支持企业在国内开展知识产权维权。资助标准为每个项目按照其实际支出成本资助，资助上限不超过50万元；项目获得的知识产权侵权相关保险赔付款、支付的和解费用应予以扣除。同一申请人每年度资助不超过1项，本项目每年资助总额不超过500万元。申请人应当是依法登记注册的企业，在深圳市从事生产经营活动，在深圳市拥有稳定办公场所，积极实施深圳市知识产权保护和运用相关规划；应建立较完善的知识产权保护制度机制，包括人员管理、合规管理、侵权预警或风险防控等。维权项目应有生效的民事判决、仲裁裁决，或达成和解经人民法院司法确认并已执行完毕；项目完成时间为上年度1月1日起至申请截止日止，以判决、裁决或和解协议生效之日为准。项目应体现企业知识产权保护能力和维权水平提升，对深圳相关产业具有借鉴作用，或对政策制定具有参考意义，或具有社会意义和影响。企业需同意将项目有关信息、研究成果、维权经验等向社会公开及供他人无偿使用，商业秘密除外。单个或多个维权事项可以合并为一个项目申报，但同一事项不可与深圳市商标品牌指导站培育资助项目中商标维权服务同类项目重复申报。已获得本市知识产权维权类专项资金资助的、行政处理或刑事诉讼方式维权的、申请人被认定构成侵权的项目不予资助；严重失信、已获市级同类资助或奖励、主体消亡或进入破产清算程序的申请人也不予资助。"
