            "龙岗政策里，前沿技术落地转化的条件尤其值得研发型机构注意。1000平方米以上办公场地、50人以上常驻研发与管理人员、近三年2项以上省级课题或重大科研项目、5篇本以上高水平论文或专著、1项行业标准和2项团体标准，这些都不是临时能补出来的。",
            "更要注意的是专利绩效。资助年度内申请发明专利不少于30项，政策期满累计授权发明专利不少于60项；如果期满少1项，按100万元标准扣减扶持资金。这种条款提醒企业：拿补贴不只是申报成功，还要持续完成绩效。",
