            "如果企业做的是无人机测试基地，重点看公共服务能力和运营费用；如果做的是低空智能融合基础设施，重点看科研实力和年度绩效；如果做的是载人航线，重点看航线数量、备案和飞行记录。不同项目不要混在一起准备，申报逻辑完全不同。",
            "资金标准也要说清楚。测试基地是最高50%运营费用补贴、每年最高300万元；前沿技术是每年2500万元扶持；载人航线是年度奖励总额不超过1500万元。企业要按自己的项目类型测算，不要只拿最高金额做对外说明。",
            "申报条件里还有几个容易忽略的点：未列入严重失信主体名单、不得弄虚作假或套取专项资金、生产经营数据真实可靠、不得同一事项重复申报或多头申报区级专项资金。这些都是底线条件。",
            "深圳金赋可以通过补贴平台先帮企业做一轮“申报适配度评估”，把适合申、暂不建议申、需要培育的方向分开。这样企业不会盲目投入时间，也能把下一批政策机会提前准备起来。",
