    while sum(len(paragraph) for paragraph in paragraphs) < TARGET_ARTICLE_CHARS and idx < len(expansions) * 2:
        base_extra = expansions[(variant + idx - 1) % len(expansions)]
        extra = f"{base_extra}{notes[(variant + idx - 1) % len(notes)]}"
        if extra not in paragraphs:
            paragraphs.insert(-1, extra)
        idx += 1
    return {
        "title": "2026年度深圳市中小试基地认定资助项目申请指南",
        "source": source,
        "valid_period": "以政策原文及后续申报指南为准",
        "max_amount": "中小试服务费用事后补助；单个项目最高1000万元",
        "from_url": url,
        "article_title": remove_unbalanced_brackets(article_title),
        "paragraphs": paragraphs,
    }



