        ("标准创新贡献奖", "一等奖和组织奖配套50万元，二等奖30万元，三等奖20万元", "获奖标准文本、获奖证明、单位与成果关系材料"),
        ("标准化人才奖励", "国际标准化人才最高200万元，国内标准化人才最高30万元", "任职材料、获奖证书、全职劳动关系证明"),
