        "很多企业不是没有标准成果，而是成果被分散放在技术、质量、市场、行政和财务部门。深圳金赋会通过补贴平台把标准文本、证书、会议资料、费用凭证和应用成效整理成机会清单，先判断哪一类更值得申。",
