    paragraph_tails = [
        f"一句话，{primary[0]}不是单纯的专业标签，它可能是企业拿补贴、拿奖励、做品牌背书的共同入口。",
        f"比如{tertiary[0]}，政策对应的是{tertiary[1]}，这个方向不一定最显眼，却适合资料比较扎实的企业做补充匹配。",
        f"别小看采用证明、推广报告和现场记录，这些材料往往能把‘做过’变成‘做成了’，也更容易说明经济效益或社会效益。",
        f"尤其是中小企业，平时没有专人盯政策，更需要把标准成果先放进一套可复用的资料库，后续申报其他项目也能接着用。",
        f"标准专项资金的机会不止一条，主导制定、参与制定、获证、培优、活动、培训、人才奖励都要分开看，别把所有成果挤进同一个口径。",
        f"企业真正要做的，是把已经发生的标准化投入变成能被政策识别的证据链：谁参与、做了什么、产生了多少支出、带来什么效果。",
        f"先评估，再取舍，再推进，这比临时抱佛脚更省心，也更符合企业做补贴规划的节奏。",
    ]
    paragraphs = [
        f"{starts[i]}{paragraph_tails[(variant + i) % len(paragraph_tails)]}" for i in range(7)
    ]
    # If an article is short because the selected phrases are compact, expand
    # existing paragraphs instead of adding many small blocks. This keeps the
    # article at 6-9 paragraphs as requested.
    expanders = [
        f"再往细处看，{primary[2]}这些资料最好不要只在申报时才整理，平时就按项目名称和年度归档，后面无论申报标准资金还是其他产业扶持，都能直接复用。",
        f"另外，{secondary[0]}也建议一并排查，{secondary[2]}如果已经具备，可以作为同一轮补贴体检里的备选项目，避免企业只盯一个入口而漏掉更容易落地的机会。",
        f"对管理层来说，这类政策的价值不只是拿一笔资金，更是倒逼企业把研发、质量、标准、市场和财务资料打通，形成以后可持续申报的资料底座。",
        f"对经办团队来说，提前核对排名、有效期、采用证明、费用口径和是否重复资助，比后期反复补材料更省时间，也能减少申报风险。",
        f"如果企业已经有标准化基础，建议把这项资金放进年度补贴规划，而不是等通知临近才想起来。补贴平台可以先帮企业做匹配，判断先冲哪类、培育哪类、放弃哪类。",
    ]
    idx = 0
    while sum(len(p) for p in paragraphs) < MIN_ARTICLE_CHARS + 80:
        target = 1 + (idx % 5)
        paragraphs[target] = f"{paragraphs[target]}{expanders[idx % len(expanders)]}"
        idx += 1
    return {
        "title": "2026年度深圳标准领域专项资金资助奖励项目申报指南",
        "source": source,
        "valid_period": "2026年6月12日9:00—7月13日18:00",
        "max_amount": "国际标准最高100万元；国际标准化人才最高200万元；标准试点示范最高50万元；深圳标准认证单项最高10万元",
        "from_url": url,
        "article_title": remove_unbalanced_brackets(article_title),
        "paragraphs": [remove_unbalanced_brackets(cleanup_generated_wording(p)).strip() for p in paragraphs],
        "skip_polish": True,
    }

