        "如果企业正在推进自主研发三类医疗器械，且产品已首次取得广东省药监部门批复的境内第三类医疗器械临床试验备案表并进入临床试验阶段，这个专题就值得重点关注。单个产品最高50万元，同一企业每年最高200万元，适合正在从研发验证迈向临床评价的器械企业把研发节点转化为政策支持。",
