        "限项核对不应只看当年新项目，还要检查正在承担的科技战略研究项目和原软科学研究项目。项目组主要成员也应核查诚信、验收和退款状态。单位可在确定课题前完成团队资格盘点，减少后续更换负责人造成的方案调整。",
        "不得委托中介申报并不意味着单位不能获得政策信息服务或专业辅导，关键是申请单位必须自主组织研究、确认资料并承担责任。任何服务都不能代替真实研究基础，也不能通过包装团队、复制方案或重复申报提高表面竞争力。",
