        "补助采用分段累进方式：测试费不超过1000万元的部分按35%；超过1000万元至2000万元的部分按25%；超过2000万元的部分按15%。单个企业最终仍受400万元年度上限约束，所有项目还共同受到年度1200万元资金总额控制。",
        "例如测试费用为800万元，按照第一档测算，理论补助为800万元乘35%，即280万元；但这只是依据政策比例的初步结果，最终还要经过费用核定、资格审核和预算统筹。合同金额不等于当然可支持金额，企业应以真实发生并符合范围的测试费为基础。",
