        "科技企业购买研发、产品或经营相关保险后，不要只把保费记入成本。企业购买纳入动态科技保险目录的产品，实际支付保险费用合计达到1万元以上并符合其他条件的，可按不超过实际保费50%获得事后补助，每年最高100万元。",
