        "本次科技金融资助采用“免申即享”和企业自主申报并行的实施方式。相关部门先推送企业名单和数据，主管部门审核后公布免申即享名单；未进入名单的企业并非完全没有机会，还可按照后续申请指南自主申报。",
        "科技类贷款项目有明确金额与期限门槛：企业应从在深圳依法经营的银行获得连续6个月以上贷款，单笔放款金额达到100万元以上，贷款本金和利息已经结清，期间不得出现欠息、逾期还款等违约行为。",
        "国家高新技术企业、科技和创新型中小企业、专精特新企业、专精特新“小巨人”企业及符合条件的科技服务企业等，迎来贷款费用和科技保险费用支持机会。企业资质还需在免申即享通知发布年度内有效。",
