        "这四类支持并非统一比例：中心展台展位费可按100%，企业展位费按70%，中心展台装修按每个标准展位最高1.5万元，配套活动最高15万元，承办费最高10万元。只有把每项费用准确归类，才能得到接近实际审核口径的资助区间。",
        "事后资助重点核验已经发生的真实投入。组团单位应把展位合同、装修合同、付款凭证、现场照片、参展企业名单和订单成果按同一展会归档，并注明市区其他资金支持情况；财政预算不足时，主管部门还可能统一调整金额及拨付进度。",
