        "生物医药与人口健康方向里，部分研究方向要求医疗卫生机构牵头，医院团队和合作单位要重点核适配度。",
        "新材料、现代农业与食品、高端装备制造与机器人、人工智能、新能源等方向都和江门产业发展有连接点，企业参与或合作空间值得关注。",
