        "如果初筛发现暂时不符合，也可以把缺口留下来，后续补制度、补台账、补翻译件，等下一轮政策窗口再评估。",
        "老板只需要先做一个动作：把海外案卷和费用台账交给深圳金赋补贴平台测一遍，能不能申、差什么材料、是否值得推进，很快就能看出方向。",
