        f"这不是只给大型企业看的项目，中小型出海企业只要海外维权事项真实、资料能闭环、保护制度有基础，也可以先测。{time_notice}",
        f"政策重点很清楚：支持企业走出去后主动维权、应对海外纠纷，并把维权经验沉淀为企业保护能力。单个项目最高200万元，受理机关和窗口期都要提前记牢。{time_notice}",
        f"申报资料不用一开始就铺得很满，先抓住结果文书、费用支出、知识产权保护制度、案件分析和影响力说明这几类。{time_notice}",
