        "普通业务总结不能直接当研究项目。企业要讲清问题从哪里来、数据怎么形成、成果解决了什么、能不能被试点或复用。",
        "实施中和已完成项目不是同一套节奏。深圳金赋会先帮企业判断项目状态，再决定是准备进展说明、可研报告，还是成果报告。",
